import re

COMMON = {"password", "123456", "qwerty", "admin", "letmein", "welcome"}

def assess(pw):
    score, notes = 0, []

    if len(pw) >= 12: score += 3; notes.append("+3  twelve characters or more")
    elif len(pw) >= 8: score += 2; notes.append("+2  at least eight characters")
    else: notes.append(" 0  too short — eight is the bare minimum")

    for label, pattern, points in [
        ("lower case", r"[a-z]", 1),
        ("upper case", r"[A-Z]", 1),
        ("a digit", r"\d", 1),
        ("a symbol", r"[^A-Za-z0-9]", 2),
    ]:
        if re.search(pattern, pw):
            score += points
            notes.append(f"+{points}  has {label}")
        else:
            notes.append(f" 0  no {label}")

    if pw.lower() in COMMON:
        score -= 4
        notes.append("-4  this is one of the most guessed passwords there is")
    if re.search(r"(.)\1{2,}", pw):
        score -= 1
        notes.append("-1  the same character three times in a row")
    if re.search(r"(abc|123|qwe)", pw.lower()):
        score -= 1
        notes.append("-1  contains a keyboard or counting run")

    verdict = "strong" if score >= 7 else "fair" if score >= 5 else "weak"
    return max(0, score), verdict, notes

for candidate in ["password", "Summer2026", "k9!Tarn-Vessel-42"]:
    score, verdict, notes = assess(candidate)
    print(f"\n{candidate!r}  ->  {score}/9  {verdict.upper()}")
    for note in notes:
        print("   ", note)

use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Room { Hall, Library, Cellar, Garden }

#[derive(Debug)]
enum Action { Go(&'static str), Take(&'static str), Look }

struct World {
    here: Room,
    exits: HashMap<Room, Vec<(&'static str, Room)>>,
    items: HashMap<Room, Vec<&'static str>>,
    bag: Vec<&'static str>,
}

impl World {
    fn new() -> Self {
        let mut exits = HashMap::new();
        exits.insert(Room::Hall, vec![("north", Room::Library), ("down", Room::Cellar)]);
        exits.insert(Room::Library, vec![("south", Room::Hall), ("east", Room::Garden)]);
        exits.insert(Room::Cellar, vec![("up", Room::Hall)]);
        exits.insert(Room::Garden, vec![("west", Room::Library)]);

        let mut items = HashMap::new();
        items.insert(Room::Library, vec!["brass key"]);
        items.insert(Room::Cellar, vec!["lantern", "rope"]);

        World { here: Room::Hall, exits, items, bag: Vec::new() }
    }

    fn act(&mut self, action: Action) {
        match action {
            Action::Look => {
                let here = self.here;
                let empty = Vec::new();
                let things = self.items.get(&here).unwrap_or(&empty);
                println!("You are in the {:?}.", here);
                if !things.is_empty() { println!("  You see: {}", things.join(", ")); }
                let ways: Vec<&str> = self.exits[&here].iter().map(|(d, _)| *d).collect();
                println!("  Exits: {}", ways.join(", "));
            }
            Action::Go(dir) => {
                match self.exits[&self.here].iter().find(|(d, _)| *d == dir) {
                    Some((_, room)) => { self.here = *room; println!("You go {} to the {:?}.", dir, room); }
                    None => println!("You cannot go {} from here.", dir),
                }
            }
            Action::Take(item) => {
                let here = self.here;
                if let Some(things) = self.items.get_mut(&here) {
                    if let Some(pos) = things.iter().position(|t| *t == item) {
                        let taken = things.remove(pos);
                        self.bag.push(taken);
                        println!("Taken: {}.", taken);
                        return;
                    }
                }
                println!("There is no {} here.", item);
            }
        }
    }
}

fn main() {
    let mut world = World::new();
    for action in [
        Action::Look,
        Action::Go("north"),
        Action::Take("brass key"),
        Action::Take("sword"),
        Action::Go("east"),
        Action::Look,
    ] {
        world.act(action);
    }
    println!("\nCarrying: {:?}", world.bag);
}

type TaskId = string;

interface Task {
  id: TaskId;
  name: string;
  minutes: number;
  needs: TaskId[];
}

const tasks: Task[] = [
  { id: 'design',  name: 'Design the schema',   minutes: 90,  needs: [] },
  { id: 'migrate', name: 'Write migrations',    minutes: 45,  needs: ['design'] },
  { id: 'api',     name: 'Build the API',       minutes: 120, needs: ['migrate'] },
  { id: 'ui',      name: 'Build the interface', minutes: 150, needs: ['design'] },
  { id: 'tests',   name: 'Write the tests',     minutes: 75,  needs: ['api', 'ui'] },
  { id: 'deploy',  name: 'Deploy',              minutes: 20,  needs: ['tests'] },
];

type Order = { ok: true; order: Task[] } | { ok: false; cycle: TaskId[] };

function schedule(all: Task[]): Order {
  const byId = new Map(all.map((t) => [t.id, t]));
  const state = new Map<TaskId, 'new' | 'open' | 'done'>();
  const order: Task[] = [];
  const stack: TaskId[] = [];

  const visit = (id: TaskId): TaskId[] | null => {
    if (state.get(id) === 'done') return null;
    if (state.get(id) === 'open') return [...stack.slice(stack.indexOf(id)), id];

    state.set(id, 'open');
    stack.push(id);
    for (const need of byId.get(id)?.needs ?? []) {
      const cycle = visit(need);
      if (cycle) return cycle;
    }
    stack.pop();
    state.set(id, 'done');
    order.push(byId.get(id)!);
    return null;
  };

  for (const t of all) {
    const cycle = visit(t.id);
    if (cycle) return { ok: false, cycle };
  }
  return { ok: true, order };
}

const result = schedule(tasks);

if (result.ok) {
  let clock = 0;
  console.log('RUN ORDER');
  for (const t of result.order) {
    const start = clock;
    clock += t.minutes;
    console.log(`  ${String(start).padStart(4)}m  ${t.name} (${t.minutes}m)`);
  }
  console.log(`\nSequential total: ${clock} minutes (${(clock / 60).toFixed(1)} hours)`);
}

// now break it on purpose
const broken: Task[] = [
  { id: 'a', name: 'A', minutes: 10, needs: ['c'] },
  { id: 'b', name: 'B', minutes: 10, needs: ['a'] },
  { id: 'c', name: 'C', minutes: 10, needs: ['b'] },
];
const bad = schedule(broken);
console.log('\nCircular check:', bad.ok ? 'fine' : `cycle found -> ${bad.cycle.join(' -> ')}`);
